import{_ as l,a0 as o,w as r,s as d,ao as i,I as e,x as p,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"如何清理 Snap 版本以釋放磁盤空間 | LCTT x X-CMD","titleTemplate":false,"description":"如何清理 Snap 版本以釋放磁盤空間 | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何清理 Snap 版本以釋放磁盤空間 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何清理 Snap 版本以釋放磁盤空間 | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221019.2 ⭐️  How to Clean Up Snap Versions to Free Up Disk Space","title":"如何清理 Snap 版本以釋放磁盤空間","tag":"202211","desc":""},"relativePath":"202211/20221019.2 ⭐️  How to Clean Up Snap Versions to Free Up Disk Space.md","filePath":"[post].md"}'),u={name:"202211/20221019.2 ⭐️  How to Clean Up Snap Versions to Free Up Disk Space.md"};function g(b,s,m,k,h,S){const n=o("Link");return r(),d("div",null,[s[26]||(s[26]=i('<h1 id="如何清理-snap-版本以釋放磁盤空間" tabindex="-1">如何清理 Snap 版本以釋放磁盤空間 <a class="header-anchor" href="#如何清理-snap-版本以釋放磁盤空間" aria-label="Permalink to “如何清理 Snap 版本以釋放磁盤空間”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/06/082905iomvvhsgoooc5czg.jpg" alt=""></p><blockquote><p>這個帶有腳本的快速指南有助於清理舊的 Snap 版本並釋放 Ubuntu 系統中的一些磁盤空間。</p></blockquote><p>我正在使用的 Ubuntu 測試系統中的磁盤空間不足。因此，我通過 GNOME 的磁盤使用分析器進行調查，以找出哪個包正在消耗寶貴的 SSD 空間。除了通常的緩存和主目錄，令我驚訝的是，我發現 Snap 和 Flatpak 消耗了大量的存儲空間。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Snap-size-before-cleanup.jpg" alt="Snap 大小 - 清理前"></p><p>儘管如此，我始終堅持一個規則：除非必要，否則不要使用 Snap 或 Flatpak。這主要是因為它們的安裝尺寸和其他問題。我更喜歡原生 deb 和 rpm 包。多年來，我在這個測試系統中安裝和移除了一定數量的 Snap 包。</p><p>但卸載後還有問題。Snap 在系統中保留了一些殘留文件，一般用户不知道。</p><p>所以我打開了 Snap 文件夾 <code>/var/lib/snapd/snaps</code>，發現 Snap 保留了以前安裝/卸載的軟件包的舊版本。</p><p>例如，在下圖中，你可以看到 GNOME 3.28、3.34 和 Wine 都被刪除了。但它們還在那裏。發生這種情況是因為 Snap 的設計，它在正確卸載後保留已卸載軟件包的版本。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Files-under-snaps-directory.jpg" alt="snaps 目錄下的文件"></p><p>或者，你可以在終端中使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>snap list --all</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/snap-list-all.jpg" alt="snap 列出全部"></p><p>對於保留的版本，默認值為 3。這意味着 Snap 會保留每個軟件包的三個舊版本，包括活動版本。如果你對磁盤空間沒有限制，這是可以的。</p><p>但是對於服務器和其他情況，這很容易遇到成本問題，它會消耗你的磁盤空間。</p><p>但是，你可以使用以下命令輕鬆修改計數。該值可以在 2 到 20 之間。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap set system refresh.retain=2</span></span></code></pre></div><h3 id="清理-snap-版本" tabindex="-1">清理 Snap 版本 <a class="header-anchor" href="#清理-snap-版本" aria-label="Permalink to “清理 Snap 版本”">​</a></h3>',18)),e("p",null,[s[1]||(s[1]=p("在 SuperUser 的一篇文章中，Canonical 的前工程經理 Popey ",-1)),a(n,{href:"https://superuser.com/a/1330590"},{default:t(()=>[...s[0]||(s[0]=[p("提供了一個簡單的腳本",-1)])]),_:1}),s[2]||(s[2]=p("，它可以清理舊版本的 Snaps 並保留最新版本。",-1))]),s[27]||(s[27]=i(`<p>這是我們將用來清理 Snap 的腳本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>#Removes old revisions of snaps</span></span>
<span class="line"><span>#CLOSE ALL SNAPS BEFORE RUNNING THIS</span></span>
<span class="line"><span>set -eu</span></span>
<span class="line"><span>LANG=en_US.UTF-8 snap list --all | awk &#39;/disabled/{print $1, $3}&#39; |</span></span>
<span class="line"><span>while read snapname revision; do</span></span>
<span class="line"><span>    snap remove &quot;$snapname&quot; --revision=&quot;$revision&quot;</span></span>
<span class="line"><span>done</span></span></code></pre></div><p>將上面的腳本以 <code>.sh</code> 擴展名保存在一個目錄中（例如 <code>clean_snap.sh</code>），賦予它可執行權限並運行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>chmod +x clean_snap.sh</span></span></code></pre></div><p>當我運行腳本後，它減少了很多磁盤空間。該腳本還將顯示要刪除的包的名稱。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Executing-the-script.jpg" alt="執行腳本"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2021/03/Snaps-size-after-cleanup.jpg" alt="清理後的 Snap 大小"></p><h3 id="結束語" tabindex="-1">結束語 <a class="header-anchor" href="#結束語" aria-label="Permalink to “結束語”">​</a></h3><p>對於 Snap 的設計效率如何，人們總是爭論不休。許多人説，它的設計是壞的，是臃腫的，是消耗系統資源的。這種説法的某些部分是真實的，我不會否認它。如果實施和加強得當，整個沙盒應用的概念是很好的。但我相信，與 Snap 相比，Flatpak 工作做得更好。</p><p>也就是説，我希望這可以幫助你清理一些磁盤空間。儘管它只在 Ubuntu 中進行了測試，但它應該適用於所有支持 Snap 的 Linux 發行版。</p>`,10)),e("p",null,[s[4]||(s[4]=p("此外，請查看我們關於 ",-1)),a(n,{href:"https://www.debugpoint.com/2018/07/4-simple-steps-clean-ubuntu-system-linux/"},{default:t(()=>[...s[3]||(s[3]=[p("如何清理 Ubuntu",-1)])]),_:1}),s[5]||(s[5]=p(" 的指南以及其他步驟。",-1))]),e("p",null,[s[7]||(s[7]=p("最後，如果你要清理 ",-1)),s[8]||(s[8]=e("strong",null,"Flatpak",-1)),s[9]||(s[9]=p(" 應用，請參閲 ",-1)),a(n,{href:"https://www.debugpoint.com/clean-up-flatpak/"},{default:t(()=>[...s[6]||(s[6]=[p("這篇指南",-1)])]),_:1}),s[10]||(s[10]=p("。",-1))]),s[28]||(s[28]=e("hr",null,null,-1)),e("p",null,[s[12]||(s[12]=p("via: ",-1)),a(n,{href:"https://www.debugpoint.com/clean-up-snap/"},{default:t(()=>[...s[11]||(s[11]=[p("https://www.debugpoint.com/clean-up-snap/",-1)])]),_:1})]),e("p",null,[s[17]||(s[17]=p("作者：",-1)),a(n,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...s[13]||(s[13]=[p("Arindam",-1)])]),_:1}),s[18]||(s[18]=p(" 選題：",-1)),a(n,{href:"https://github.com/lkxed"},{default:t(()=>[...s[14]||(s[14]=[p("lkxed",-1)])]),_:1}),s[19]||(s[19]=p(" 譯者：",-1)),a(n,{href:"https://github.com/geekpi"},{default:t(()=>[...s[15]||(s[15]=[p("geekpi",-1)])]),_:1}),s[20]||(s[20]=p(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[p("wxy",-1)])]),_:1})]),e("p",null,[s[23]||(s[23]=p("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[p("LCTT",-1)])]),_:1}),s[24]||(s[24]=p(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[p("Linux中國",-1)])]),_:1}),s[25]||(s[25]=p(" 榮譽推出",-1))])])}const T=l(u,[["render",g]]);export{C as __pageData,T as default};
